<?php
const RETURN_REASONS=['wrong_item'=>['Wrong product received','ভুল পণ্য পেয়েছি'],'damaged'=>['Damaged on arrival','ক্ষতিগ্রস্ত পণ্য পেয়েছি'],'defective'=>['Defective product','ত্রুটিপূর্ণ পণ্য'],'not_as_described'=>['Not as described','বিবরণের সঙ্গে মিল নেই']];
function return_policy():array{$defaults=['enabled'=>true,'days'=>3,'version'=>1,'conditions_en'=>'Returns are accepted for wrong, damaged, defective or materially misdescribed products. Size preference and change of mind are not covered. Keep the product and packaging for inspection where possible. Do not send a parcel before approval.','conditions_bn'=>'ভুল, ক্ষতিগ্রস্ত, ত্রুটিপূর্ণ বা বিবরণের সঙ্গে গুরুত্বপূর্ণ অমিল থাকা পণ্যের রিটার্ন গ্রহণ করা হয়। সাইজ পছন্দ না হওয়া বা মত বদলানো গ্রহণযোগ্য কারণ নয়। যাচাইয়ের জন্য সম্ভব হলে পণ্য ও প্যাকেজিং রাখুন। অনুমোদনের আগে পার্সেল পাঠাবেন না।','instructions_en'=>'Apply from your order details. The store will confirm return transport, costs and a refund or replacement after review. No automatic refund or courier pickup is triggered by a request.','instructions_bn'=>'আপনার অর্ডারের বিস্তারিত থেকে আবেদন করুন। যাচাইয়ের পর স্টোর ফেরত পাঠানোর ব্যবস্থা, খরচ এবং refund বা replacement নিশ্চিত করবে। আবেদন করলেই স্বয়ংক্রিয় টাকা ফেরত বা কুরিয়ার পিকআপ হবে না।'];return array_replace($defaults,json_decode(setting('return_policy','{}'),true)?:[]);}
function order_return_policy(array $o):array{$p=json_decode($o['return_policy_snapshot']??'null',true);return is_array($p)&&isset($p['days'])?$p:return_policy();}
function return_eligibility(array $o):array{$p=order_return_policy($o);$days=(int)$p['days'];$base=['days'=>$days,'deadline'=>null,'mode'=>'ineligible','can_request'=>false];if(!$p['enabled'])return $base+['reason'=>'policy_disabled'];if(!in_array($o['status'],['Delivered','Partially delivered']))return $base+['reason'=>'not_delivered'];if($o['status']==='Partially delivered'||empty($o['delivered_at']))return array_replace($base,['can_request'=>true,'mode'=>'manual_review','reason'=>'delivery_verification']);$at=strtotime($o['delivered_at'].' UTC');if(!$at||$at>time()+300)return array_replace($base,['can_request'=>true,'mode'=>'manual_review','reason'=>'delivery_verification']);$deadline=$at+$days*86400;return array_replace($base,['deadline'=>gmdate('c',$deadline),'can_request'=>time()<=$deadline,'mode'=>time()<=$deadline?'eligible':'ineligible','reason'=>time()<=$deadline?'within_window':'window_closed']);}
function return_order_meta(array $o):array{$requests=query('SELECT id,reference,status,reason,created_at FROM return_requests WHERE order_id=? ORDER BY id DESC',[$o['id']])->fetchAll();$used=query("SELECT ri.order_item_id,SUM(ri.quantity) quantity FROM return_items ri JOIN return_requests r ON r.id=ri.return_id WHERE r.order_id=? AND r.status NOT IN ('rejected','cancelled') GROUP BY ri.order_item_id",[$o['id']])->fetchAll(PDO::FETCH_KEY_PAIR);$eligible=return_eligibility($o);return ['eligibility'=>$eligible,'requests'=>$requests,'reserved_quantities'=>$used];}
function return_case(array $r,bool $admin=false):array{if(!$admin)unset($r['internal_note'],$r['request_key']);$r['items']=query('SELECT ri.order_item_id,ri.quantity,oi.name,oi.image,oi.size,oi.price FROM return_items ri JOIN order_items oi ON oi.id=ri.order_item_id WHERE ri.return_id=?',[$r['id']])->fetchAll();$r['events']=query('SELECT status,note,created_at FROM return_events WHERE return_id=? ORDER BY id',[$r['id']])->fetchAll();$r['evidence']=query('SELECT id FROM return_evidence WHERE return_id=?',[$r['id']])->fetchAll(PDO::FETCH_COLUMN);$r['policy_snapshot']=json_decode($r['policy_snapshot'],true);return $r;}
function return_notify(array $r,string $status):void{$text='Return '.str_replace('_',' ',$status);emit_event('order-status','user',['order_id'=>(int)$r['order_id'],'status'=>$text,'return_id'=>(int)$r['id']],(int)$r['user_id']);emit_event('order-updated','admin',['order_id'=>(int)$r['order_id'],'status'=>$text,'return_id'=>(int)$r['id']]);}
function create_return_request(array $u,array $input):array{global $db;$oid=(int)($input['order_id']??0);$key=(string)($input['request_key']??'');if(!preg_match('/^[a-zA-Z0-9-]{20,64}$/',$key))throw new RuntimeException('Reload the return form and try again.');$reason=$input['reason']??'';if(!isset(RETURN_REASONS[$reason]))throw new RuntimeException('Choose a wrong, damaged, defective or misdescribed-product reason.');$description=trim((string)($input['description']??''));if(mb_strlen($description)<10||mb_strlen($description)>2000)throw new RuntimeException('Describe the problem in 10–2,000 characters.');$preferred=$input['preferred_resolution']??'refund';if(!in_array($preferred,['refund','replacement']))throw new RuntimeException('Choose refund or replacement.');$items=$input['items']??[];if(!is_array($items)||!$items||count($items)>50)throw new RuntimeException('Select at least one purchased item to return.');$evidence=array_values(array_unique($input['evidence']??[]));if(count($evidence)>3)throw new RuntimeException('Attach no more than three photos.');$db->beginTransaction();try{$o=query('SELECT * FROM orders WHERE id=? AND user_id=? FOR UPDATE',[$oid,$u['id']])->fetch();if(!$o)throw new RuntimeException('This order is not available in your account.');$old=query('SELECT * FROM return_requests WHERE request_key=?',[$key])->fetch();if($old){if($old['user_id']!=$u['id']||$old['order_id']!=$oid)throw new RuntimeException('Reload the return form and try again.');$db->commit();return $old;}$elig=return_eligibility($o);if(!$elig['can_request'])throw new RuntimeException($elig['reason']==='window_closed'?'The return window has closed. Contact the store for assistance.':'Return requests are available only for eligible delivered orders.');$p=order_return_policy($o);$lines=[];foreach($items as $it){$iid=(int)($it['order_item_id']??0);$qty=filter_var($it['quantity']??null,FILTER_VALIDATE_INT);if(isset($lines[$iid])||$qty===false||$qty<1)throw new RuntimeException('Choose each purchased item once with a valid quantity.');$line=query('SELECT * FROM order_items WHERE id=? AND order_id=?',[$iid,$oid])->fetch();if(!$line)throw new RuntimeException('One selected item does not belong to this order.');$used=(int)query("SELECT COALESCE(SUM(ri.quantity),0) FROM return_items ri JOIN return_requests r ON r.id=ri.return_id WHERE ri.order_item_id=? AND r.status NOT IN ('rejected','cancelled')",[$iid])->fetchColumn();if($qty>$line['quantity']-$used)throw new RuntimeException('This quantity is already returned or reserved by another request.');$lines[$iid]=$qty;}foreach($evidence as $eid){$ev=query('SELECT id FROM return_evidence WHERE id=? AND order_id=? AND user_id=? AND return_id IS NULL FOR UPDATE',[$eid,$oid,$u['id']])->fetch();if(!$ev)throw new RuntimeException('One evidence photo is unavailable or belongs to a different order.');}$ref='RT-'.strtoupper(bin2hex(random_bytes(5)));query('INSERT INTO return_requests(reference,order_id,user_id,request_key,reason,description,preferred_resolution,eligibility_mode,policy_snapshot) VALUES(?,?,?,?,?,?,?,?,?)',[$ref,$oid,$u['id'],$key,$reason,$description,$preferred,$elig['mode'],json_encode($p,JSON_UNESCAPED_UNICODE)]);$id=(int)$db->lastInsertId();foreach($lines as $iid=>$qty)query('INSERT INTO return_items(return_id,order_item_id,quantity) VALUES(?,?,?)',[$id,$iid,$qty]);foreach($evidence as $eid)query('UPDATE return_evidence SET return_id=? WHERE id=?',[$id,$eid]);query('INSERT INTO return_events(return_id,status,note,actor_id) VALUES(?,?,?,?)',[$id,'requested',$elig['mode']==='manual_review'?'Request received. Delivery/eligibility must be verified by the store.':'Request received. Awaiting store review.',$u['id']]);$db->commit();$r=query('SELECT * FROM return_requests WHERE id=?',[$id])->fetch();audit('return-requested',['return_id'=>$id,'order_id'=>$oid]);return_notify($r,'requested');return $r;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
